+		return nil, err
+	}
+	fields := strings.Split(out, "\x00")
+	entries := make([]HistoryEntry, 0, len(fields)/3)
+	for i := 0; i+2 < len(fields); i += 3 {
+		if fields[i] == "" {
+			continue
+		}
+		entry := HistoryEntry{Commit: fields[i], Subject: fields[i+1]}
+		for _, line := range strings.Split(fields[i+2], "\n") {
