		return err
	}
	changed, err := gitutil.ChangedFiles(ctx, repo, base, view.revision, nil)
	if err != nil {
		return err
	}
	baseSnapshot, err := gpsSnapshotRevision(ctx, opts, repo, base, true)
	if err != nil {
		return err
	}
	headSnapshot, err := gpsSnapshotRevision(ctx, opts, repo, view.revision, true)
	if err != nil {
		return err
	}
