	for _, delta := range deltas {
		if delta["id"] != "GPS-DELTA-ANCHOR" {
			continue
		}
		id, _ := delta["subject"].(string)
		for _, binding := range set.Bindings {
			if binding.ID == id {
				anchors[id] = binding.Selector.File
			}
		}
