}

func TestPR237OldCommitEvidence(t *testing.T) {
 repo := copyGPSFixture(t, "token-auth")
 set, err := intent.Load(repo); if err != nil { t.Fatal(err) }
 path := filepath.Join(t.TempDir(), "evidence.json")
