 if err := os.WriteFile(path,data,0600); err != nil { t.Fatal(err) }
 got := gpsExecutionEvidence(path,set)
 if got["status"] == "CURRENT" { t.Fatalf("unrelated old-commit evidence marked CURRENT: %v",got) }
}

func TestPR237ReviewDisposition(t *testing.T) {
 for _, mode := range []string{"changed_test", "partial_graph"} {
 t.Run(mode,func(t *testing.T) {
 repo := copyGPSFixture(t,"token-auth")
