 gpsGit(t,repo,"config","user.name","Review Fixture")
 gpsGit(t,repo,"config","user.email","review@example.invalid")
 gpsGit(t,repo,"config","core.hooksPath","/dev/null")
 gpsGit(t,repo,"add",".")
 gpsGit(t,repo,"commit","-qm","base")
 base:=gpsRevision(t,repo)
 if mode=="changed_test" {
  path:=filepath.Join(repo,"auth_test.go")
  data,err:=os.ReadFile(path);if err!=nil {t.Fatal(err)}
  data=[]byte(strings.Replace(string(data),"tokenLifetimeSeconds <= 0","tokenLifetimeSeconds < 0",1))
  if err:=os.WriteFile(path,data,0644);err!=nil {t.Fatal(err)}
 } else {
  if err:=os.WriteFile(filepath.Join(repo,"broken.go"),[]byte("package auth\nfunc Broken( {\n"),0644);err!=nil {t.Fatal(err)}
 }
 gpsGit(t,repo,"add",".");gpsGit(t,repo,"commit","-qm",mode)
 var out bytes.Buffer
 if err:=Run(t.Context(),Options{Version:"test",Env:EntireEnv{RepoRoot:repo},Stdout:&out},[]string{"review","--repo",repo,"--base",base});err!=nil {t.Fatal(err)}
 var result map[string]any
 if err:=json.Unmarshal(out.Bytes(),&result);err!=nil {t.Fatal(err)}
